template:
enum Command {
    Click { x: i32, y: i32 },
    Reset,
}

fn total(cmd: Command) -> i32 {
    match cmd {
        ⟦click_pattern⟧ => x + y,
        ⟦reset_pattern⟧ => 0,
    }
}

fn main() {
    println!("{}", total(Command::Click { x: 3, y: 4 }));
}

tests:
#[test]
fn total_click() {
    assert_eq!(total(Command::Click { x: 3, y: 4 }), 7);
    assert_eq!(total(Command::Reset), 0);
}
